package com.example.complaintmanagement.mapper; import com.example.complaintmanagement.entity.*; import com.example.complaintmanagement.dto.*; public class ComplaintMapper { private final UserMapper um=new UserMapper(); private final CategoryMapper cm=new CategoryMapper(); public ComplaintDtos.Response toResponse(Complaint c){ return new ComplaintDtos.Response(c.getId(),c.getComplaintNumber(),c.getTitle(),c.getDescription(),c.getStatus(),c.getPriority(),cm.toResponse(c.getCategory()),um.toResponse(c.getCreatedBy()),c.getAssignedTo()==null?null:um.toResponse(c.getAssignedTo()),c.getResolutionNote(),s(c.getCreatedAt()),s(c.getUpdatedAt()),s(c.getResolvedAt()),s(c.getClosedAt())); } private String s(java.time.LocalDateTime t){return t==null?null:t.toString();} }